def propagate_color(matrix, color):
    """Propagate color from middle row to above and below."""
    changed = True
    while changed:
        changed = False
        for r in range(1, len(matrix) - 1):
            # Get all cells of this color in current cell's column in the row above
            cells_above = {(r-1, c) for c in range(len(matrix[r-1])) if matrix[r-1][c] == color}
