            cells_left = {(r, c-1) for c in range(len(matrix[r])) if matrix[r][c] == color and c > 0}
            cells_right = {(r, c+1) for c in range(len(matrix[r])) if matrix[r][c] == color and c < len(matrix[r]) - 1}

